-- Generated by tools/dim/import_scans.py. 14 image-only questions: Riyaziyyat test toplusu I (2025), bölmə 7.
-- Run once in Supabase SQL Editor. Safe to re-run: the topic is created only if missing, questions are upserted by code.
-- Upload the images (out/upload_kitab/*.webp) to the question-images bucket too.
set standard_conforming_strings = on;
begin;

do $$
begin
  if not exists (select 1 from subjects where slug = 'riyaziyyat') then
    raise exception 'subjects cədvəlində slug=riyaziyyat yoxdur';
  end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
                  where t.typname = 'exam_level' and e.enumlabel = 'qebul') then
    raise exception 'exam_level enum-unda qebul etiketi yoxdur: import dayandırıldı';
  end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
                  where t.typname = 'question_type' and e.enumlabel = 'aciq_eded') then
    raise exception 'question_type enum-unda aciq_eded etiketi yoxdur: import dayandırıldı';
  end if;
  if (select count(*) from pg_enum e join pg_type t on t.oid = e.enumtypid
       where t.typname = 'question_type' and e.enumlabel in ('aciq_eded', 'qapali', 'uygunlasdirma')) <> 3 then
    raise exception 'question_type enum-unda lazımi etiketlər yoxdur (migration 014?): import dayandırıldı';
  end if;
end $$;

-- section and topic (only if missing)
insert into topics (subject_id, parent_id, name, sort_order)
select s.id, null, 'Adi və onluq kəsrlər', 50 from subjects s where s.slug = 'riyaziyyat'
on conflict (subject_id, parent_id, name) do nothing;

insert into topics (subject_id, parent_id, name, sort_order)
select s.id, p.id, 'Kəsrlərin müqayisəsi', 30
  from subjects s join topics p on p.subject_id = s.id and p.parent_id is null and p.name = 'Adi və onluq kəsrlər'
 where s.slug = 'riyaziyyat'
on conflict (subject_id, parent_id, name) do nothing;

insert into questions (code, topic_id, type, body, image_path, options, correct_answer, difficulty, solution,
                       exam_levels, groups, year, source, source_ref, is_active)
select v.code, t.id, v.type::question_type, '', v.image_path, v.options::jsonb, v.correct,
       3::smallint, null, array['qebul']::exam_level[], '{}'::smallint[], 2025::smallint, 'DİM',
       'Riyaziyyat test toplusu I (2025), bölmə 7' || ', sual ' || (regexp_match(v.code, 'Q(\d+)$'))[1]::int, true
  from (values
  ('RT1-S07-Q001', 'RT1-S07-Q001.webp', 'A', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q002', 'RT1-S07-Q002.webp', 'D', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q003', 'RT1-S07-Q003.webp', 'E', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q004', 'RT1-S07-Q004.webp', 'B', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q005', 'RT1-S07-Q005.webp', 'D', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q006', 'RT1-S07-Q006.webp', 'D', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q007', 'RT1-S07-Q007.webp', 'A', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q008', 'RT1-S07-Q008.webp', 'A', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q009', 'RT1-S07-Q009.webp', 'C', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q010', 'RT1-S07-Q010.webp', 'C', 'qapali', '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'),
  ('RT1-S07-Q011', 'RT1-S07-Q011.webp', '40', 'aciq_eded', null),
  ('RT1-S07-Q012', 'RT1-S07-Q012.webp', '24', 'aciq_eded', null),
  ('RT1-S07-Q013', 'RT1-S07-Q013.webp', 'BC;A;D', 'uygunlasdirma', '{"1": "ABCDE", "2": "ABCDE", "3": "ABCDE"}'),
  ('RT1-S07-Q014', 'RT1-S07-Q014.webp', 'C;D;A', 'uygunlasdirma', '{"1": "ABCDE", "2": "ABCDE", "3": "ABCDE"}')
       ) as v(code, image_path, correct, type, options)
  join subjects s on s.slug = 'riyaziyyat'
  join topics sec on sec.subject_id = s.id and sec.parent_id is null and sec.name = 'Adi və onluq kəsrlər'
  join topics t on t.subject_id = s.id and t.parent_id = sec.id and t.name = 'Kəsrlərin müqayisəsi'
on conflict (code) do update set
  topic_id = excluded.topic_id, type = excluded.type, image_path = excluded.image_path, options = excluded.options,
  correct_answer = excluded.correct_answer, source_ref = excluded.source_ref, is_active = excluded.is_active;

do $$
declare n integer;
begin
  select count(*) into n from questions where code in ('RT1-S07-Q001', 'RT1-S07-Q002', 'RT1-S07-Q003', 'RT1-S07-Q004', 'RT1-S07-Q005', 'RT1-S07-Q006', 'RT1-S07-Q007', 'RT1-S07-Q008', 'RT1-S07-Q009', 'RT1-S07-Q010', 'RT1-S07-Q011', 'RT1-S07-Q012', 'RT1-S07-Q013', 'RT1-S07-Q014');
  if n <> 14 then
    raise exception 'Gözlənilən 14 sual, bazada % tapıldı: geri alınır', n;
  end if;
end $$;

commit;

select count(*) as yuklenen_sual from questions where code like 'RT1-S07-%';
